import numpy as np
from PIL import Image
im = np.asarray(Image.open('barcode.png').convert('RGB')).astype(float)
cols = im.mean(axis=0)
w = cols.shape[0]
def at(frac, half=0.02):
    a = max(0, int((frac-half)*w)); b = min(w, int((frac+half)*w))
    c = cols[a:b].mean(axis=0)
    return '#%02x%02x%02x' % tuple(int(round(x)) for x in c)
for f in [0.05,0.10,0.15,0.20,0.25,0.30,0.35,0.40,0.45,0.50,0.55,0.60,0.65,0.70,0.75,0.80,0.85,0.90,0.95]:
    print(f"{int(f*100):3d}%: {at(f)}")
EOF"}

